/// <summary>
/// READING GUIDE: PD is the semantic validation view of PDF dictionaries: pages,
/// resources, fonts, annotations, actions and structure trees. Implementations
/// derive these facts from parser objects and effective document/graphics state.
/// This schema is not the parser&apos;s org.verapdf.pd implementation package.
/// C# PORT: Generate/implement custom interfaces over parser domain objects.
/// The CLR has no built-in PDPage, PDFont or PDF/A validation equivalents.
/// Keep raw-key presence flags separate from resolved optional links: presence
/// does not imply correct type, successful resolution or a valid value.
/// Preserve exact property/link names for rule lookup, even if C# API names use
/// PascalCase. See README.md for scalar types, multiplicity and missing values.
/// base class for all PD layer objects
/// </summary>
/// <remarks>Source: PDLayer.mdl; Java: org.verapdf.model.pdlayer.PDObject.
/// </remarks>
public interface IPDObject : global::VeraPdf.Model.BaseLayer.IModelObject
{
    /// <summary>
    /// C# PORT: objectKey is PDF object number plus generation, not a CLR hash,
    /// memory address or file offset. Preserve entries&apos; ampersand-delimited format.
    /// ampersand separated list of entries
    /// </summary>
    /// <remarks>DSL String; may be absent or invalid. Java getter: getentries.</remarks>
    string? Getentries();
    /// <summary>
    /// indirect object number and generation number for the current object
    /// </summary>
    /// <remarks>DSL String; may be absent or invalid. Java getter: getobjectKey.</remarks>
    string? GetobjectKey();
}

